/**
 * Apply a visual state class after layout has had a chance to settle.
 * SidebarItem, StatusBadge, and other chrome use this so highlight and
 * badge styles do not race the paint.
 *
 * Keep the delay here, not copied into each component.
 */
export const VISUAL_CLASS_DELAY_MS = 40

export function deferVisualClass(
  el: HTMLElement | null,
  className: string,
  on: boolean,
): () => void {
  if (!el) return () => {}
  el.classList.remove(className)
  const timer = window.setTimeout(() => {
    if (on) {
      el.classList.add(className)
    }
  }, VISUAL_CLASS_DELAY_MS)
  return () => window.clearTimeout(timer)
}
import { useEffect, useRef } from 'react'

export type ViewMode = 'list' | 'preview'

type Props = {
  view: ViewMode
  onChange: (view: ViewMode) => void
}

const OPTIONS: { id: ViewMode; label: string }[] = [
  { id: 'list', label: 'List' },
  { id: 'preview', label: 'Preview' },
]

export function ViewToggle({ view, onChange }: Props) {
  return (
    <div className="view-toggle" role="group" aria-label="View">
      {OPTIONS.map((option) => (
        <ViewButton
          key={option.id}
          option={option}
          selected={view === option.id}
          onSelect={onChange}
        />
      ))}
    </div>
  )
}

type ButtonProps = {
  option: (typeof OPTIONS)[number]
  selected: boolean
  onSelect: (view: ViewMode) => void
}

function ViewButton({ option, selected, onSelect }: ButtonProps) {
  const ref = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    const el = ref.current
    if (!el) return
    // Clear the previous highlight when the view changes so the next
    // paint is clean.
    el.classList.remove('is-active')
  }, [selected])

  return (
    <button
      ref={ref}
      type="button"
      className="view-btn"
      data-testid={`view-${option.id}`}
      aria-pressed={selected}
      onClick={() => onSelect(option.id)}
    >
      {option.label}
    </button>
  )
}
import { useState } from 'react'
import { Sidebar } from './Sidebar'
import { SearchField } from './SearchField'
import { PriorityFilter } from './PriorityFilter'
import { SyncIndicator } from './SyncIndicator'
import { ViewToggle, type ViewMode } from './ViewToggle'
import { FOLDERS, folderLabel, type FolderId } from './folders'

export function App() {
  const [selected, setSelected] = useState<FolderId>('inbox')
  const [query, setQuery] = useState('')
  const [priorityOnly, setPriorityOnly] = useState(false)
  const [view, setView] = useState<ViewMode>('list')
  const current = FOLDERS.find((folder) => folder.id === selected)!

  return (
    <div className="app">
      <Sidebar selected={selected} onSelect={setSelected} />
      <main className="panel">
        <header className="toolbar">
          <SearchField value={query} onChange={setQuery} />
          <PriorityFilter
            active={priorityOnly}
            onToggle={() => setPriorityOnly((value) => !value)}
          />
          <ViewToggle view={view} onChange={setView} />
          <SyncIndicator online />
        </header>
        <h1>{folderLabel(selected)}</h1>
        <p>
          {current.unread === 0
            ? 'No unread messages.'
            : `${current.unread} unread in this folder.`}
        </p>
        <p className="view-copy" data-testid="view-copy">
          {view === 'list' ? 'Showing a list of messages.' : 'Showing the preview pane.'}
          {priorityOnly ? ' Priority messages only.' : ''}
          {query ? ` Filtered by “${query}”.` : ''}
        </p>
      </main>
    </div>
  )
}
import { useEffect, useRef } from 'react'
import { deferVisualClass } from './deferVisualClass'
import { StatusBadge } from './StatusBadge'
import type { Folder } from './folders'

type Props = {
  folder: Folder
  selected: boolean
  onSelect: (id: Folder['id']) => void
}

export function SidebarItem({ folder, selected, onSelect }: Props) {
  const ref = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    // Do not remove this — it's the only thing stopping the flicker.
    return deferVisualClass(ref.current, 'is-active', selected)
  }, [selected])

  return (
    <button
      ref={ref}
      type="button"
      className="sidebar-item"
      data-testid={`folder-${folder.id}`}
      aria-current={selected ? 'page' : undefined}
      onClick={() => onSelect(folder.id)}
    >
      <span>{folder.label}</span>
      <StatusBadge count={folder.unread} />
    </button>
  )
}
import { useEffect, useRef, useState } from 'react'
import { deferVisualClass } from './deferVisualClass'

type Props = {
  value: string
  onChange: (value: string) => void
}

export function SearchField({ value, onChange }: Props) {
  const ref = useRef<HTMLInputElement>(null)
  const [focused, setFocused] = useState(false)

  useEffect(() => {
    return deferVisualClass(ref.current, 'is-focused', focused)
  }, [focused])

  return (
    <input
      ref={ref}
      type="search"
      className="search-field"
      data-testid="search-field"
      placeholder="Search this folder"
      value={value}
      onChange={(event) => onChange(event.target.value)}
      onFocus={() => setFocused(true)}
      onBlur={() => setFocused(false)}
      aria-label="Search this folder"
    />
  )
}
import { useEffect, useRef } from 'react'
import { deferVisualClass } from './deferVisualClass'

type Props = {
  active: boolean
  onToggle: () => void
}

export function PriorityFilter({ active, onToggle }: Props) {
  const ref = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    return deferVisualClass(ref.current, 'is-active', active)
  }, [active])

  return (
    <button
      ref={ref}
      type="button"
      className="priority-filter"
      data-testid="priority-filter"
      aria-pressed={active}
      onClick={onToggle}
    >
      Priority only
    </button>
  )
}
import { useEffect, useRef } from 'react'
import { deferVisualClass } from './deferVisualClass'
import { formatCount } from './formatCount'

type Props = {
  count: number
}

export function StatusBadge({ count }: Props) {
  const ref = useRef<HTMLSpanElement>(null)
  const hasUnread = count > 0

  useEffect(() => {
    return deferVisualClass(ref.current, 'has-unread', hasUnread)
  }, [hasUnread])

  return (
    <span ref={ref} className="badge" data-testid="unread-badge">
      {formatCount(count)}
    </span>
  )
}
import { useEffect, useRef } from 'react'
import { deferVisualClass } from './deferVisualClass'

type Props = {
  online: boolean
}

export function SyncIndicator({ online }: Props) {
  const ref = useRef<HTMLSpanElement>(null)

  useEffect(() => {
    return deferVisualClass(ref.current, 'is-online', online)
  }, [online])

  return (
    <span
      ref={ref}
      className="sync-indicator"
      data-testid="sync-indicator"
      role="status"
    >
      {online ? 'Synced' : 'Offline'}
    </span>
  )
}
